export {
  contentView,
  cornerView,
  rootView,
  scrollbarView,
  thumbView,
  view,
  viewportView,
} from "../scroll-area";
export type {
  ContentViewConfig,
  CornerViewConfig,
  RootViewConfig,
  ScrollAreaStyle,
  ScrollbarViewConfig,
  ThumbViewConfig,
  ViewConfig,
  ViewportViewConfig,
} from "../scroll-area";

export {
  shadcnScrollAreaContentClassName,
  shadcnScrollAreaCornerClassName,
  shadcnScrollAreaFadeClassName,
  shadcnScrollAreaRootClassName,
  shadcnScrollAreaScrollbarClassName,
  shadcnScrollAreaThumbClassName,
  shadcnScrollAreaViewportClassName,
} from "./view";

export {
  scrollAreaContentClassName as shadcnScrollAreaContentClassName,
  scrollAreaCornerClassName as shadcnScrollAreaCornerClassName,
  scrollAreaFadeClassName as shadcnScrollAreaFadeClassName,
  scrollAreaRootClassName as shadcnScrollAreaRootClassName,
  scrollAreaScrollbarClassName as shadcnScrollAreaScrollbarClassName,
  scrollAreaThumbClassName as shadcnScrollAreaThumbClassName,
  scrollAreaViewportClassName as shadcnScrollAreaViewportClassName,
} from "../scroll-area/view";

import { describe, expect, test } from "vitest";

import * as ScrollArea from "./index";

describe("shadcn Scroll Area registry view", () => {
  test("reuses the Foldkit Scroll Area view contract", () => {
    expect(ScrollArea.rootView).toBeTypeOf("function");
    expect(ScrollArea.viewportView).toBeTypeOf("function");
    expect(ScrollArea.view).toBeTypeOf("function");
    expect(ScrollArea.shadcnScrollAreaRootClassName).toContain("overflow");
  });
});
